-- 20260805122000_equipment_backfill.sql
--
-- Phase 4 of the equipment register
-- (docs/plans/2026-08-05-equipment-tracking.md): the 25 rows of the
-- "Assets & Equipment" tab, with their custody history.
--
-- People were resolved by hand against company_os.people. The spreadsheet
-- writes names without diacritics ("Nguyen Chi Hieu"), the database keeps them
-- ("Nguyen Chi Hieu" -> "Nguyễn Chí Hiếu"), so matching is deliberately a fixed
-- map rather than a fuzzy join.
--
-- Two names could NOT be resolved and are imported with no holder rather than
-- guessed at:
--   * "Le Dinh Ngoc"           — both "Ngoc Le" and "Loc Dinh" are plausible.
--   * "Nguyen Duy Khanh Chieu" — a prior holder; the only near match is a
--                                job_seeker, not confidently the same person.
-- Both carry a note on the record. The phase 5 physical audit resolves them.
--
-- Vendors are NOT linked: the vendor directory currently holds cars, tours and
-- venues, and none of the electronics retailers (FPT, CellphoneS, DiDongViet,
-- Phuong Tin, T&T Center) exist in it. Rather than inventing vendor rows as a
-- side effect of an import, each supplier is kept verbatim in vendor_name_raw.
--
-- Re-runnable guard: the whole import is skipped if equipment already has rows.

do $$
begin
  if (select count(*) from company_os.equipment) > 0 then
    raise notice 'company_os.equipment is not empty; backfill skipped.';
    return;
  end if;
end $$;

do $$
declare v_id uuid;
begin
end $$;
